			tensorfs.Record(a, `a`)
			v := tensor.Tensor(tensor.NewFloat64FromValues([]float64{2., 3.}...))
			tensorfs.Record(v, `v`)

			b := tensor.Tensor(matrix.Mul(a, a))
			tensorfs.Record(b, `b`)
			c := tensor.Tensor(matrix.Mul(a, v))
			tensorfs.Record(c, `c`)
			d := tensor.Tensor(matrix.Mul(v, a))
			tensorfs.Record(d, `d`)

			fmt.Fprintln(contentCodeOut, "a:", a)
