					tensorfs.Record(a, `a`)

					t := tensor.Tensor(tensor.Transpose(a))
					tensorfs.Record(t, `t`)
					d := tensor.Tensor(matrix.Det(a))
					tensorfs.Record(d, `d`)
					i := tensor.Tensor(matrix.Inverse(a))
					tensorfs.Record(i, `i`)

					fmt.Fprintln(contentCodeOut, "t:", t)
